describe("Cart - pricing pipeline", () => {
  it("computes subtotal as sum of unitPrice * quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 100), 2);
    cart.add(product("b", 300), 1);
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(500);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
