toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any input", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 10000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(1.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 1.5)).toThrow(RangeError);
    });

    it("accepts valid params", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat rate for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100)], 1000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
    });

    it("returns flat rate when subtotal below freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            1.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
      { upToGrams: 2000, costCents: 900 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const noWeight: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
      ];
      expect(calc.computeShippingCents(noWeight, 1000)).toBe(0);
    });

    it("selects first bracket at boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket just over first boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
    });

    it("selects last bracket at its boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 2000)], 1000)).toBe(900);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(900);
    });

    it("uses overflowCostCents when provided", () => {
      const withOverflow = new WeightBasedShippingCalculator(
        [{ upToGrams: 500, costCents: 300 }],
        1500,
      );
      expect(
        withOverflow.computeShippingCents([makeLine("a", 1000)], 0),
      ).toBe(1500);
    });

    it("accumulates weight across multiple lines", () => {
      // 2 items × 300g = 600g → falls into second bracket (501-1000)
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(600);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted = new WeightBasedShippingCalculator([
        { upToGrams: 1000, costCents: 600 },
        { upToGrams: 500, costCents: 300 },
      ]);
      expect(unsorted.computeShippingCents([makeLine("a", 400)], 0)).toBe(300);
    });
  });
});

